// ============================================================
// PRE-REQUEST — RF-G9-01 Reporte de movimientos agrupados
// Todas las variables viven en pm.collectionVariables
// ============================================================

const sqlBaseUrl = pm.collectionVariables.get('sqlSandboxBaseUrl');
const sqlApiKey  = pm.collectionVariables.get('sqlSandboxApiKey');

function querySandbox(sql, params, callback) {
    pm.sendRequest({
        url: `${sqlBaseUrl}/api/v1/sql/select`,
        method: 'POST',
        header: {
            'Content-Type': 'application/json',
            'x-api-key': sqlApiKey
        },
        body: {
            mode: 'raw',
            raw: JSON.stringify({ sql, params: params || [] })
        }
    }, (err, res) => {
        if (err) return callback(err, null);
        if (res.code !== 200) {
            return callback(new Error(`SQL ${res.code}: ${JSON.stringify(res.json())}`), null);
        }
        callback(null, res.json().data || []);
    });
}

// PASO 1 — elegir usuarioId con movimientos reales
querySandbox(
    `SELECT usuario_id, COUNT(*) AS total_movs
     FROM movimientos
     GROUP BY usuario_id
     ORDER BY total_movs DESC
     LIMIT 1`,
    [],
    (err, rows) => {
        if (err) {
            console.error('❌ Pre-request paso 1 falló:', err.message);
            pm.execution.skipRequest();
            return;
        }
        if (!rows.length) {
            console.warn('⚠️ No hay movimientos; se aborta el request');
            pm.execution.skipRequest();
            return;
        }

        const usuarioId = rows[0].usuario_id;
        pm.collectionVariables.set('g9_usuario_id', usuarioId);
        pm.collectionVariables.set('g9_movs_esperados', Number(rows[0].total_movs));
        console.log(`✅ usuarioId capturado: ${usuarioId} (${rows[0].total_movs} movimientos)`);

        // PASO 2 — rango real de fechas
        querySandbox(
            `SELECT MIN(created_at) AS desde, MAX(created_at) AS hasta
             FROM movimientos
             WHERE usuario_id = $1`,
            [usuarioId],
            (err2, rows2) => {
                if (err2) {
                    console.error('❌ Pre-request paso 2 falló:', err2.message);
                    pm.execution.skipRequest();
                    return;
                }

                if (rows2.length) {
                    pm.collectionVariables.set('g9_desde', rows2[0].desde);
                    pm.collectionVariables.set('g9_hasta', rows2[0].hasta);
                    console.log(`✅ Rango: ${rows2[0].desde} → ${rows2[0].hasta}`);
                }

                // PASO 3 — tipos de movimiento esperados
                querySandbox(
                    `SELECT DISTINCT tipo_movimiento
                     FROM movimientos
                     WHERE usuario_id = $1`,
                    [usuarioId],
                    (err3, rows3) => {
                        if (err3) {
                            console.error('❌ Pre-request paso 3 falló:', err3.message);
                            pm.execution.skipRequest();
                            return;
                        }
                        const tipos = rows3.map(r => r.tipo_movimiento);
                        pm.collectionVariables.set('g9_tipos_esperados', JSON.stringify(tipos));
                        console.log(`✅ Tipos: ${tipos.join(', ')}`);
                    }
                );
            }
        );
    }
);

