            ).to.eql(totalDBRango);
            done();
        }
    );
});

// --- AC-G9-01c: totales por tipo coinciden con DB ---
pm.test("AC-G9-01c: Totales por tipo coinciden con DB", function (done) {
    querySandbox(
        `SELECT tipo_movimiento, COUNT(*) AS cantidad, SUM(monto) AS total
         FROM movimientos
         WHERE usuario_id = $1
         GROUP BY tipo_movimiento
         ORDER BY tipo_movimiento`,
        [usuarioId],
        (err, res) => {
            if (err) {
                done(err);
                return;
            }
            const rows = res.data || [];

            const dbPorTipo = {};
            rows.forEach(r => {
                dbPorTipo[r.tipo_movimiento] = {
                    cantidad: Number(r.cantidad),
                    total: Number(r.total)      // ✅ normalizado
                };
            });

            jsonData.data.forEach(item => {
                const db = dbPorTipo[item.tipo_movimiento];
                pm.expect(db, 
                    `Tipo ${item.tipo_movimiento} debe existir en DB`
                ).to.exist;

                pm.expect(Number(item.cantidad),
                    `cantidad de ${item.tipo_movimiento}`
                ).to.eql(db.cantidad);

                pm.expect(parseFloat(item.total),
                    `total de ${item.tipo_movimiento}`
                ).to.eql(db.total);
            });
            done();
        }
    );
});

